package main

import (
	"fmt"
	"go/format"
	"log"
	"slices"
	"sort"
	"strings"
)

// symbolsFile is the generated file that holds Symbols, in internal/vmsdef.
const symbolsFile = "symbols_generated.go"

// mergeResult says what merging one input's definitions did.
type mergeResult struct {
	added     []string // names new to the table, sorted
	changed   []string // "NAME: old -> new", for each value -replace changed
	conflicts []string // the same, for each value that wasn't replaced
	same      int      // names already in the table with the same value
}

// mergeSymbols merges defs into symbols. A name new to symbols is added;
// one already there with the same value is left alone; one with another
// value is a conflict, and changed only if replace is true.
func mergeSymbols(symbols, defs map[string]uint32, replace bool) mergeResult {
	var r mergeResult

	names := make([]string, 0, len(defs))
	for name := range defs {
		names = append(names, name)
	}

	sort.Strings(names)

	for _, name := range names {
		v := defs[name]

		old, ok := symbols[name]

		switch {
		case !ok:
			symbols[name] = v
			r.added = append(r.added, name)

		case old == v:
			r.same++

		case replace:
			symbols[name] = v
			r.changed = append(r.changed, fmt.Sprintf("%s: %#x -> %#x", name, old, v))

		default:
			r.conflicts = append(r.conflicts, fmt.Sprintf("%s: %#x, not %#x", name, old, v))
		}
	}

	return r
}

// addSource adds name to sources, unless it's there already.
func addSource(sources []string, name string) []string {
	if slices.Contains(sources, name) {
		return sources
	}

	return append(sources, name)
}

// generateSymbols returns the Go source of symbols_generated.go.
func generateSymbols(symbols map[string]uint32, sources []string) []byte {
	var b strings.Builder

	fmt.Fprintf(&b, "// Code generated by internal/vmsdef/gen. DO NOT EDIT.\n\n")
	fmt.Fprintf(&b, "package vmsdef\n\n")

	fmt.Fprintf(&b, "// SymbolSources names the VMS definition files Symbols was built from,\n")
	fmt.Fprintf(&b, "// in the order they were first merged.\n")
	fmt.Fprintf(&b, "var SymbolSources = []string{\n")

	for _, s := range sources {
		fmt.Fprintf(&b, "\t%q,\n", s)
	}

	fmt.Fprintf(&b, "}\n\n")

	names := make([]string, 0, len(symbols))
	for name := range symbols {
		names = append(names, name)
	}

	sort.Strings(names)

	fmt.Fprintf(&b, "// Symbols is every VMS symbolic constant govax knows, by name: the\n")
	fmt.Fprintf(&b, "// values of $SSDEF, $FABDEF, $IODEF, and the other definition files.\n")
	fmt.Fprintf(&b, "// See symbols.go for what each prefix holds.\n")
	fmt.Fprintf(&b, "var Symbols = map[string]uint32{\n")

	for _, name := range names {
		fmt.Fprintf(&b, "\t%q: %#x,\n", name, symbols[name])
	}

	fmt.Fprintf(&b, "}\n")

	out, err := format.Source([]byte(b.String()))
	if err != nil {
		log.Fatalf("gen: generated source doesn't compile: %v", err)
	}

	return out
}
